INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM205FH1E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'From the top of a $41$-meter-tall building, the angle of depression to a point on the ground is $\\theta$, where $\\tan(\\theta) = \\frac{41}{58}$. What is the horizontal distance, in meters, from the base of the building to the point on the ground?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '58', ARRAY['58'], E'The angle of depression from the top of the building to the ground point equals the angle of elevation from the ground point to the top of the building (alternate interior angles with horizontal lines). Using the tangent ratio, $\\tan(\\theta) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{41}{d}$, where $d$ is the horizontal distance. Given $\\tan(\\theta) = \\frac{41}{58}$, we have $\\frac{41}{d} = \\frac{41}{58}$, so $d = 58$ meters. A common error is to confuse opposite and adjacent sides and compute $d = \\frac{58}{41} \\times 41 = 58$ but then report the building height $41$ instead. Another error is to compute the line-of-sight distance using the Pythagorean theorem: $\\sqrt{41^2 + 58^2} = \\sqrt{1681 + 3364} = \\sqrt{5045} \\approx 71$, which is not the horizontal distance.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21Z8W9U', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $\\frac{42x^{11}}{7x^4}$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^7$"},{"key":"B","text":"$35x^7$"},{"key":"C","text":"$6x^{15}$"},{"key":"D","text":"$35x^{15}$"}]$lyceon_json$::jsonb, 'A', NULL, E'To divide monomials, divide the coefficients and subtract the exponents: $\\frac{42}{7} = 6$ and $x^{11} \\div x^4 = x^{11-4} = x^7$, giving $6x^7$. The distractor $35x^7$ results from subtracting the coefficients ($42 - 7 = 35$) instead of dividing them. The distractor $6x^{15}$ results from adding the exponents ($11 + 4 = 15$) instead of subtracting them. The distractor $35x^{15}$ combines both errors — subtracting the coefficients and adding the exponents.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22XSC3D', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'The ages (in years) of $10$ participants in a study are: $19$, $22$, $24$, $25$, $27$, $31$, $33$, $36$, $41$, $52$. If the participant aged $52$ is replaced by a participant aged $34$, which of the following must be true?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the median stays the same"},{"key":"B","text":"The mean decreases and the median increases"},{"key":"C","text":"The mean stays the same and the median increases"},{"key":"D","text":"Both the mean and the median decrease"}]$lyceon_json$::jsonb, 'A', NULL, E'The original sum is $19 + 22 + 24 + 25 + 27 + 31 + 33 + 36 + 41 + 52 = 310$, giving a mean of $31$. Replacing $52$ with $34$ yields a new sum of $310 - 52 + 34 = 292$, so the new mean is $29.2$. The mean decreases. For the median of $10$ values, average the $5$th and $6$th values in sorted order. The original sorted list is $19, 22, 24, 25, 27, 31, 33, 36, 41, 52$, so the median is $\\frac{27 + 31}{2} = 29$. The new sorted list is $19, 22, 24, 25, 27, 31, 33, 34, 36, 41$, so the median is still $\\frac{27 + 31}{2} = 29$. The median stays the same because the $5$th and $6$th values are unchanged. The option stating both measures decrease is wrong because the median is unaffected by replacing an extreme value that was not in the middle two positions. The option stating the median increases is wrong because the $5$th and $6$th positions remain $27$ and $31$. The option stating the mean stays the same ignores that substituting $34$ for $52$ reduces the sum by $18$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM237QV21', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'grid_in', E'What is the $y$-intercept of the line $8x + 3y = 39$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The $y$-intercept occurs when $x = 0$. Substituting $x = 0$ into the equation gives $3y = 39$, so $y = 13$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23CV1L4', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'grid_in', E'In triangle $ABC$, the measure of angle $A$ is $(3x + 11)°$, the measure of angle $B$ is $(5x - 7)°$, and the measure of angle $C$ is $(2x + 6)°$. What is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'The sum of the interior angles of a triangle is $180°$. Setting up the equation: $(3x + 11) + (5x - 7) + (2x + 6) = 180$. Combining like terms: $10x + 10 = 180$. Subtracting $10$ from both sides: $10x = 170$. Dividing by $10$: $x = 17$. To verify: angle $A = 3(17) + 11 = 62°$, angle $B = 5(17) - 7 = 78°$, angle $C = 2(17) + 6 = 40°$, and $62 + 78 + 40 = 180°$. A common error is to combine the constant terms incorrectly, such as computing $11 - 7 + 6 = 8$ instead of $10$, which would yield $10x = 172$ and $x = 17.2$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23DE3KK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = (x - 13)(x + 5)$. What is the $x$-coordinate of the vertex of the graph of $y = g(x)$ in the $xy$-plane?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$9$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'B', NULL, E'For a quadratic in factored form $(x - r_1)(x - r_2)$, the $x$-coordinate of the vertex is the average of the roots. The roots of $g(x) = (x - 13)(x + 5)$ are $x = 13$ and $x = -5$. The average is $\\frac{13 + (-5)}{2} = \\frac{8}{2} = 4$. The distractor $-4$ results from a sign error when averaging the roots. The distractor $9$ results from adding the root values without the sign ($\\frac{13 + 5}{2} = 9$) instead of using $-5$. The distractor $13$ results from selecting just one of the roots rather than averaging them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23TJURC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'If $f(x) = 5x^2 + 3x - 7$, what is the value of $f(-3)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '29', ARRAY['29'], E'Substituting $x = -3$ into the function: $f(-3) = 5(-3)^2 + 3(-3) - 7 = 5(9) - 9 - 7 = 45 - 9 - 7 = 29$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24JLJ4B', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $$\\frac{x^2 - 121}{x^2 + 6x - 55} \\cdot \\frac{x^2 - 25}{x^2 - 22x + 121}$$ for all values of $x$ where it is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x - 5}{x + 11}$"},{"key":"B","text":"$\\frac{x + 5}{x + 11}$"},{"key":"C","text":"$\\frac{x + 5}{x - 11}$"},{"key":"D","text":"$\\frac{x - 5}{x - 11}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Factor each polynomial: $x^2 - 121 = (x + 11)(x - 11)$, $x^2 + 6x - 55 = (x + 11)(x - 5)$, $x^2 - 25 = (x + 5)(x - 5)$, and $x^2 - 22x + 121 = (x - 11)^2$. The product becomes $$\\frac{(x+11)(x-11)}{(x+11)(x-5)} \\cdot \\frac{(x+5)(x-5)}{(x-11)^2}.$$ Cancelling the common factors $(x + 11)$, $(x - 5)$, and one $(x - 11)$ yields $\\frac{x + 5}{x - 11}$. The distractor $\\frac{x - 5}{x + 11}$ results from retaining the cancelled factors rather than the remaining ones. The distractor $\\frac{x + 5}{x + 11}$ results from an error in tracking the denominator factor after cancellation, keeping $(x + 11)$ instead of $(x - 11)$. The distractor $\\frac{x - 5}{x - 11}$ results from a sign error that replaces $(x + 5)$ with $(x - 5)$ in the numerator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM252PI7B', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What is the value of $x$ in the equation $11x - 43 = 23$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Add $43$ to both sides to get $11x = 66$. Divide both sides by $11$ to find $x = 6$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM255KDMD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $47°$ and the measure of angle $Q$ is $68°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$55°$"},{"key":"B","text":"$65°$"},{"key":"C","text":"$75°$"},{"key":"D","text":"$115°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180°$. Therefore, angle $R = 180° - 47° - 68° = 65°$. The answer $65°$ is correct. The answer $55°$ results from a subtraction error such as computing $180 - 47 - 68$ as $180 - 125 = 55$. The answer $75°$ results from a different arithmetic slip, such as miscalculating $47 + 68$ as $105$ instead of $115$. The answer $115°$ is the sum of the two given angles rather than the supplement, confusing the exterior angle theorem with the interior angle sum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26DIRSA', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one leg has length $11$ and the hypotenuse has length $61$. What is the length of the other leg?', NULL, $lyceon_json$[{"key":"A","text":"$50$"},{"key":"B","text":"$60$"},{"key":"C","text":"$72$"},{"key":"D","text":"$\\sqrt{3842}$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Pythagorean theorem, $a^2 + b^2 = c^2$. With $a = 11$ and $c = 61$: $11^2 + b^2 = 61^2$, so $121 + b^2 = 3721$, giving $b^2 = 3600$ and $b = 60$. The value $50$ comes from simply subtracting $61 - 11$ instead of applying the Pythagorean theorem. The value $72$ results from an arithmetic error when computing $\\sqrt{3600}$. The value $\\sqrt{3842}$ comes from adding $11^2 + 61^2 = 121 + 3721 = 3842$ instead of subtracting, which confuses finding a leg with finding a hypotenuse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27153OH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has the equation $x^2 + y^2 + 8x - 12y + 3 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{3}$"},{"key":"B","text":"$4$"},{"key":"C","text":"$7$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'C', NULL, E'Complete the square for both variables. Group and rearrange: $(x^2 + 8x) + (y^2 - 12y) = -3$. Complete the square for $x$: $x^2 + 8x + 16 = (x + 4)^2$, adding $16$ to both sides. Complete the square for $y$: $y^2 - 12y + 36 = (y - 6)^2$, adding $36$ to both sides. The equation becomes $(x + 4)^2 + (y - 6)^2 = -3 + 16 + 36 = 49$. Since $r^2 = 49$, the radius is $r = 7$. The value $\\sqrt{3}$ comes from taking the square root of the original constant $3$ without completing the square. The value $4$ is half of the $x$-coefficient $8$, which is the $x$-coordinate of the center, not the radius. The value $49$ is $r^2$, not $r$ itself.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM285RQGX', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $f(x) = 2x + b$, where $b$ is a constant, has the property that $f(f(3)) = 33$. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$9$"},{"key":"C","text":"$21$"},{"key":"D","text":"$27$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, $f(3) = 2(3) + b = 6 + b$. Then $f(f(3)) = f(6 + b) = 2(6 + b) + b = 12 + 2b + b = 12 + 3b$. Setting this equal to $33$: $12 + 3b = 33$, so $3b = 21$ and $b = 7$. Verification: $f(3) = 13$, $f(13) = 33$. The distractor $9$ results from not distributing the $2$ over the entire expression $(6 + b)$, computing $f(6 + b)$ as $6 + 2b + b = 6 + 3b$ instead of $12 + 3b$, which gives $6 + 3b = 33$ and $b = 9$. The distractor $21$ comes from correctly reaching $3b = 21$ but reporting $21$ instead of dividing by $3$. The distractor $27$ results from solving $f(3) = 33$ directly (i.e., $6 + b = 33$, so $b = 27$), treating the problem as a single application of $f$ rather than a composition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28MT0B5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $250$ commuters in a city found that $83$ use public transit. The margin of error for this estimate is $\\pm 5\\%$. Which of the following is the best estimate of the range of the percentage of all commuters who use public transit?', NULL, $lyceon_json$[{"key":"A","text":"$28.2\\%$ to $38.2\\%$"},{"key":"B","text":"$30.7\\%$ to $35.7\\%$"},{"key":"C","text":"$33.2\\%$ to $38.2\\%$"},{"key":"D","text":"$27.2\\%$ to $39.2\\%$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sample proportion is $\\frac{83}{250} = 33.2\\%$. Applying the margin of error of $\\pm 5\\%$ gives the interval $33.2\\% - 5\\% = 28.2\\%$ to $33.2\\% + 5\\% = 38.2\\%$. The distractor $30.7\\%$ to $35.7\\%$ uses half the margin of error ($\\pm 2.5\\%$) instead of the full $\\pm 5\\%$. The distractor $33.2\\%$ to $38.2\\%$ adds the margin only above the sample proportion, treating the interval as one-sided. The distractor $27.2\\%$ to $39.2\\%$ uses $\\pm 6\\%$ instead of the stated $\\pm 5\\%$, reflecting a computation error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28T4P4O', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'A $45°$-$45°$-$90°$ triangle has a hypotenuse of length $14\\sqrt{2}$. What is the length of each leg?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$7\\sqrt{2}$"},{"key":"C","text":"$14$"},{"key":"D","text":"$14\\sqrt{2}$"}]$lyceon_json$::jsonb, 'C', NULL, E'In a $45°$-$45°$-$90°$ triangle, the sides are in the ratio $x : x : x\\sqrt{2}$, where $x$ is the length of each leg and $x\\sqrt{2}$ is the hypotenuse. Setting $x\\sqrt{2} = 14\\sqrt{2}$ gives $x = 14$. Each leg has length $14$. The value $7$ results from dividing $14\\sqrt{2}$ by $2$ instead of by $\\sqrt{2}$. The value $7\\sqrt{2}$ comes from dividing $14\\sqrt{2}$ by $2$ without simplifying the radical, conflating two operations. The value $14\\sqrt{2}$ is the hypotenuse itself, not the leg.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM290SGDG', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What are all values of $x$ that satisfy the inequality $11x - 33 \\geq 44$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\geq 1$"},{"key":"B","text":"$x \\leq 7$"},{"key":"C","text":"$x \\geq 7$"},{"key":"D","text":"$x \\geq 77$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding $33$ to both sides gives $11x \\geq 77$. Dividing both sides by $11$ yields $x \\geq 7$. The value $x \\geq 1$ results from subtracting $33$ from $44$ to get $11$ and then dividing $11 \\div 11 = 1$, an arithmetic slip in the direction of the first step. The value $x \\leq 7$ has the correct boundary value but reverses the inequality direction, a sign error. The value $x \\geq 77$ stops at the intermediate result $11x \\geq 77$ without dividing by $11$, reflecting partial reasoning.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29P2LH1', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'grid_in', E'If $g(x) = -4x + 31$, what is the value of $g(8)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-1', ARRAY['-1'], E'Substitute $x = 8$ into the function: $g(8) = -4(8) + 31 = -32 + 31 = -1$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BHU978', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $17$, $23$, $23$, $29$, $35$. What is the mean of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$25.4$"},{"key":"C","text":"$27$"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'B', NULL, E'The mean is $\\frac{17 + 23 + 23 + 29 + 35}{5} = \\frac{127}{5} = 25.4$. The distractor $23$ is the median and mode of the data set, not the mean — selecting it reflects confusing measures of center. The distractor $27$ results from an arithmetic error when summing the values (for example, getting $135$ instead of $127$). The distractor $29$ is simply one of the data values, not the mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C0Y4JL', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ that satisfies $\\frac{3x + 5}{2} - \\frac{x + 1}{3} = x + 4$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$11$"},{"key":"C","text":"$21$"},{"key":"D","text":"$37$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiply every term by the LCD $6$: $3(3x + 5) - 2(x + 1) = 6(x + 4)$. Distribute: $9x + 15 - 2x - 2 = 6x + 24$, so $7x + 13 = 6x + 24$. Subtract $6x$: $x + 13 = 24$. Subtract $13$: $x = 11$. The distractor $7$ arises from a sign error distributing $-2(x + 1)$ as $-2x + 2$ instead of $-2x - 2$, yielding $7x + 17 = 6x + 24$ and $x = 7$. The distractor $21$ comes from an arithmetic slip in which the constant in $3(3x + 5)$ is computed as $9x + 5$ (forgetting to multiply $5$ by $3$), giving $7x + 3 = 6x + 24$ and $x = 21$. The distractor $37$ results from adding $13 + 24 = 37$ in the step $7x + 13 = 6x + 24$ instead of subtracting to isolate $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C1AUWG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'In a school of $320$ students, $75\\%$ passed a final exam. Of the students who passed, $20\\%$ scored above $90$. How many students scored above $90$?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$48$"},{"key":"C","text":"$64$"},{"key":"D","text":"$240$"}]$lyceon_json$::jsonb, 'B', NULL, E'The number of students who passed is $0.75 \\times 320 = 240$. Of those, $20\\%$ scored above $90$: $0.20 \\times 240 = 48$ students. The distractor $16$ results from applying $20\\%$ to the $80$ students who did not pass ($0.20 \\times 80 = 16$), using the wrong group. The distractor $64$ results from applying $20\\%$ directly to the total $320$ students ($0.20 \\times 320 = 64$), ignoring that the $20\\%$ applies only to those who passed. The distractor $240$ is the total number of students who passed, not the number who scored above $90$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CBMVV7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A bookstore has $54$ customers on a Saturday. Of these, $31$ browse fiction and $23$ browse nonfiction. Among those who browse fiction, $14$ make a purchase. Among those who browse nonfiction, $9$ make a purchase. If a customer is selected at random from those who made a purchase, what is the probability that the customer browsed nonfiction?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{54}$"},{"key":"B","text":"$\\frac{14}{23}$"},{"key":"C","text":"$\\frac{9}{31}$"},{"key":"D","text":"$\\frac{9}{23}$"}]$lyceon_json$::jsonb, 'D', NULL, E'The total number of customers who made a purchase is $14 + 9 = 23$. Among these $23$ purchasers, $9$ browsed nonfiction. Therefore the conditional probability is $\\frac{9}{23}$. The distractor $\\frac{9}{54}$ divides by the total number of customers instead of restricting to those who purchased. The distractor $\\frac{14}{23}$ uses the number of fiction purchasers in the numerator, answering about fiction rather than nonfiction. The distractor $\\frac{9}{31}$ divides by the number of fiction browsers instead of the total purchasers, mixing the wrong denominator group.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DAL5PU', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $p(d) = 420 - 17d$ models the number of pages remaining in a book after $d$ days of reading at a constant rate. What does the number $17$ represent in this function?', NULL, $lyceon_json$[{"key":"A","text":"The total number of pages in the book"},{"key":"B","text":"The number of pages read per day"},{"key":"C","text":"The number of days needed to finish the book"},{"key":"D","text":"The number of pages remaining after $17$ days"}]$lyceon_json$::jsonb, 'B', NULL, E'In the linear function $p(d) = 420 - 17d$, the coefficient of $d$ represents the rate of change. Since $p$ decreases by $17$ for every increase of $1$ in $d$, the number $17$ is the number of pages read per day. The total number of pages in the book is $420$ (the constant term when $d = 0$), not $17$. The number of days needed to finish the book would be found by solving $420 - 17d = 0$, giving $d \\approx 24.7$, which is a computed quantity, not what $17$ directly represents. The number of pages remaining after $17$ days would be $p(17) = 420 - 289 = 131$, which is a computed output for a specific input, not the meaning of the coefficient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DL10UE', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$$7x - 3y = 29$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EAVJ5T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A jacket originally priced at $\\$85$ is on sale for $\\$59.50$. What percent discount was applied to the jacket?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '30', ARRAY['30'], E'The discount amount is $85 - 59.50 = \\$25.50$. The percent discount is $\\frac{25.50}{85} \\times 100 = 30\\%$. A common error is computing $\\frac{59.50}{85} \\times 100 = 70\\%$, which gives the percentage of the original price that the customer pays rather than the discount percentage.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EDS38W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A nutritionist wants to determine whether drinking green tea daily reduces cholesterol levels. She randomly assigns $35$ participants to drink green tea every day for $12$ weeks and $35$ participants to drink plain water instead, then measures their cholesterol levels at the end of the study. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"An observational study, because the nutritionist measured cholesterol levels without any intervention"},{"key":"B","text":"An experiment, because the nutritionist randomly assigned participants to treatment groups"},{"key":"C","text":"A survey, because the nutritionist collected health data from participants"},{"key":"D","text":"A case study, because individual participants' cholesterol was tracked"}]$lyceon_json$::jsonb, 'B', NULL, E'The defining characteristic of an experiment is that the researcher randomly assigns subjects to treatment and control groups. Here, the nutritionist randomly assigned participants to either drink green tea or plain water, imposing a treatment. The choice calling it an observational study incorrectly claims there was no intervention, when in fact the nutritionist imposed the green tea regimen. The choice calling it a survey misuses the term, since surveys involve questionnaires or self-reported data, not controlled treatments. The choice calling it a case study misapplies the term, which refers to in-depth analysis of a single subject or small group without controlled comparison.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EUCPXI', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'At a print shop, $6$ notebooks and $5$ binders cost a total of $\\$47$. At the same shop, $3$ notebooks and $5$ binders cost a total of $\\$29$. What is the total cost, in dollars, of $9$ notebooks?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '54', ARRAY['54'], E'Let $n$ represent the cost of one notebook and $b$ represent the cost of one binder. The system is $6n + 5b = 47$ and $3n + 5b = 29$. Subtracting the second equation from the first eliminates $b$: $(6n + 5b) - (3n + 5b) = 47 - 29$, giving $3n = 18$, so $n = 6$. The cost of $9$ notebooks is $9 \\times 6 = 54$ dollars. Verification: substituting $n = 6$ into $3(6) + 5b = 29$ gives $5b = 11$, so $b = 2.20$; then $6(6) + 5(2.20) = 36 + 11 = 47$, confirming the solution.', NULL, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FLKBTU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = -5x + 47$. According to this model, what is the predicted value of $y$ when $x = 7$?', NULL, $lyceon_json$[{"key":"A","text":"$-12$"},{"key":"B","text":"$2$"},{"key":"C","text":"$12$"},{"key":"D","text":"$82$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 7$ gives $y = -5(7) + 47 = -35 + 47 = 12$. The distractor $-12$ results from a sign error, computing $35 - 47 = -12$ by treating the slope as positive and then subtracting $47$. The distractor $2$ comes from an arithmetic miscalculation such as $-35 + 37$. The distractor $82$ results from adding instead of subtracting: $35 + 47 = 82$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GQ9ZR7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up a product by $60\\%$ over its wholesale cost and then offers a $25\\%$ employee discount on the marked-up price. If an employee pays $\\$46.20$ for the product, what was the wholesale cost?', NULL, $lyceon_json$[{"key":"A","text":"$\\$28.88$"},{"key":"B","text":"$\\$38.50$"},{"key":"C","text":"$\\$46.20$"},{"key":"D","text":"$\\$61.60$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the wholesale cost be $w$. The marked-up price is $1.60w$, and after the $25\\%$ employee discount, the price is $0.75 \\times 1.60w = 1.20w$. Setting $1.20w = 46.20$ gives $w = \\frac{46.20}{1.20} = 38.50$. The distractor $\\$28.88$ results from dividing $46.20$ by $1.60$ alone, applying only the markup multiplier without incorporating the discount. The distractor $\\$46.20$ treats the employee''s price as the wholesale cost, ignoring both the markup and discount entirely. The distractor $\\$61.60$ results from dividing $46.20$ by $0.75$, reversing only the discount step without also reversing the markup.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H4BZU6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'The line of best fit for a data set is $y = 2.5x + 13$. One of the data points is $(6, 31)$. What is the residual for this data point?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'The predicted value at $x = 6$ is $y = 2.5(6) + 13 = 15 + 13 = 28$. The residual is the actual value minus the predicted value: $31 - 28 = 3$. A common error is computing predicted minus actual ($28 - 31 = -3$), which reverses the sign of the residual. Another error is reporting the predicted value $28$ itself instead of computing the difference.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HWK12O', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'A circle passes through the points $(1, 8)$ and $(11, 8)$, and its center lies on the line $y = x - 3$. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$25\\pi$"},{"key":"B","text":"$50\\pi$"},{"key":"C","text":"$75\\pi$"},{"key":"D","text":"$100\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since the circle passes through $(1, 8)$ and $(11, 8)$, the center must lie on the perpendicular bisector of the segment connecting these points. The midpoint is $(6, 8)$, and since the segment is horizontal, the perpendicular bisector is the vertical line $x = 6$. The center also lies on $y = x - 3$, so substituting $x = 6$ gives $y = 3$. The center is $(6, 3)$. The radius is the distance from $(6, 3)$ to $(1, 8)$: $r = \\sqrt{(6 - 1)^2 + (3 - 8)^2} = \\sqrt{25 + 25} = \\sqrt{50} = 5\\sqrt{2}$. The area is $\\pi r^2 = \\pi(5\\sqrt{2})^2 = 50\\pi$. The value $25\\pi$ comes from using only the horizontal distance $|6 - 1| = 5$ as the radius, ignoring the vertical component. The value $75\\pi$ results from an arithmetic error when computing $r^2$, such as getting $25 + 50 = 75$. The value $100\\pi$ comes from using the full distance between the two given points, $|11 - 1| = 10$, as the radius instead of computing the distance from the center.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I4IMOB', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A bakery makes cupcakes and cakes for a fundraiser. Each cupcake uses $3$ ounces of batter and each cake uses $11$ ounces. The bakery has at most $400$ ounces of batter available and can display at most $100$ items total. If the bakery must make at least $17$ cakes, what is the maximum number of cupcakes it can make?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '71', ARRAY['71'], E'Let $c$ represent the number of cupcakes and $k$ the number of cakes. The constraints are $c + k \\leq 100$, $3c + 11k \\leq 400$, and $k \\geq 17$. To maximize $c$, minimize $k$ by setting $k = 17$. The display constraint gives $c \\leq 100 - 17 = 83$. The batter constraint gives $3c \\leq 400 - 11(17) = 400 - 187 = 213$, so $c \\leq 71$. Since $71 < 83$, the batter constraint is the binding one, and the maximum number of cupcakes is $71$. Verification: $3(71) + 11(17) = 213 + 187 = 400 \\leq 400$, and $71 + 17 = 88 \\leq 100$. Trying $c = 72$: $3(72) + 11(17) = 216 + 187 = 403 > 400$, which exceeds the batter supply, confirming $71$ is the maximum.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I8FYDY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In the figure, lines $m$ and $n$ are parallel, and line $t$ is a transversal. The angle on the left side of $t$ above line $m$ measures $(4x + 19)°$, and the angle on the right side of $t$ below line $n$ measures $(7x - 23)°$. These two angles are alternate exterior angles. What is the measure, in degrees, of the angle on the left side of $t$ above line $m$?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$56$"},{"key":"C","text":"$75$"},{"key":"D","text":"$105$"}]$lyceon_json$::jsonb, 'C', NULL, E'Alternate exterior angles formed by parallel lines and a transversal are congruent, so $4x + 19 = 7x - 23$. Subtracting $4x$ from both sides: $19 = 3x - 23$. Adding $23$: $42 = 3x$, so $x = 14$. The angle measure is $4(14) + 19 = 56 + 19 = 75°$. The value $14$ is just the value of $x$, not the angle measure itself. The value $56$ comes from computing only $4x = 4(14) = 56$ and omitting the constant $19$. The value $105$ results from computing $180° - 75° = 105°$, giving the supplementary angle instead of the requested angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2INIMLG', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $m$ has the equation $4x - 9y = 36$. What is the equation of the line that is perpendicular to line $m$ and has the same $y$-intercept as line $m$?', NULL, $lyceon_json$[{"key":"A","text":"$4x + 9y = -36$"},{"key":"B","text":"$9x - 4y = 16$"},{"key":"C","text":"$9x + 4y = -16$"},{"key":"D","text":"$9x + 4y = 16$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewrite line $m$ in slope-intercept form: $4x - 9y = 36$ becomes $y = \\frac{4}{9}x - 4$, so the slope of $m$ is $\\frac{4}{9}$ and the $y$-intercept is $-4$. The perpendicular slope is the negative reciprocal: $-\\frac{9}{4}$. The new line has equation $y = -\\frac{9}{4}x - 4$. Multiplying by $4$: $4y = -9x - 16$, so $9x + 4y = -16$. The distractor $4x + 9y = -36$ results from negating the slope of $m$ to get $-\\frac{4}{9}$ instead of taking the negative reciprocal, giving $y = -\\frac{4}{9}x - 4$, which converts to $4x + 9y = -36$. The distractor $9x - 4y = 16$ comes from using the reciprocal $\\frac{9}{4}$ without negating, yielding $y = \\frac{9}{4}x - 4$ and $-9x + 4y = -16$, then incorrectly writing $9x - 4y = 16$. The distractor $9x + 4y = 16$ results from an arithmetic slip that uses $+4$ instead of $-4$ for the $y$-intercept, giving $y = -\\frac{9}{4}x + 4$ and $9x + 4y = 16$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L3J7BD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A rectangular garden measures $11$ meters by $7$ meters. A path of uniform width $2$ meters surrounds the garden on all sides. What is the area, in square meters, of the path alone?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '88', ARRAY['88'], E'The outer rectangle, including the path, has dimensions $(11 + 2 \\times 2)$ by $(7 + 2 \\times 2) = 15$ by $11$ meters. The outer area is $15 \\times 11 = 165$ square meters. The garden area is $11 \\times 7 = 77$ square meters. The area of the path is $165 - 77 = 88$ square meters. A common error is to add only one width of the path to each dimension instead of two (one on each side), computing $(11 + 2)(7 + 2) = 117$ and then $117 - 77 = 40$. Another error is to compute the outer area but forget to subtract the garden, reporting $165$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MCUGTV', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What value of $x$ satisfies the equation $3(2x + 7) - 4 = 5(x - 1) + 2$?', NULL, $lyceon_json$[{"key":"A","text":"$-20$"},{"key":"B","text":"$-18$"},{"key":"C","text":"$-10$"},{"key":"D","text":"$2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distribute on both sides: $6x + 21 - 4 = 5x - 5 + 2$, which simplifies to $6x + 17 = 5x - 3$. Subtract $5x$ from both sides: $x + 17 = -3$. Subtract $17$: $x = -20$. The distractor $-18$ results from an arithmetic slip computing $21 - 4 = 15$ instead of $17$, yielding $6x + 15 = 5x - 3$ and $x = -18$. The distractor $-10$ comes from a sign error distributing $5(x - 1)$ as $5x + 5$, giving $6x + 17 = 5x + 7$ and $x = -10$. The distractor $2$ results from failing to distribute the $3$, solving $2x + 7 - 4 = 5x - 3$ as $2x + 3 = 5x - 3$, which gives $6 = 3x$ and $x = 2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MVRRFA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A research firm surveyed $380$ randomly selected homeowners and found that $41\\%$ plan to install solar panels within the next $5$ years, with a margin of error of $\\pm 4.7\\%$. A local newspaper reported that fewer than half of homeowners plan to install solar panels. Which of the following best evaluates the newspaper''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is not supported because the upper bound of the confidence interval exceeds $50\\%$."},{"key":"B","text":"The claim is supported because the entire confidence interval is below $50\\%$."},{"key":"C","text":"The claim cannot be evaluated without knowing the total number of homeowners in the area."},{"key":"D","text":"The claim is supported only if the confidence level is $99\\%$ or higher."}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval is $41\\% - 4.7\\% = 36.3\\%$ to $41\\% + 4.7\\% = 45.7\\%$. Since the entire interval lies below $50\\%$, the data support the claim that fewer than half of homeowners plan to install solar panels. The distractor stating the upper bound exceeds $50\\%$ reflects a computation error, since $45.7\\%$ is well below $50\\%$. The distractor requiring the total population size is irrelevant because the margin of error already accounts for sampling precision. The distractor requiring a $99\\%$ confidence level introduces an unnecessary condition; the margin of error already incorporates the chosen confidence level.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NNPHFM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A recipe calls for $\\frac{7}{4}$ cups of sugar to make $14$ servings. How many cups of sugar are needed to make $22$ servings?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/4', ARRAY['11/4', '2.75'], E'The rate of sugar per serving is $\\frac{7/4}{14} = \\frac{7}{56} = \\frac{1}{8}$ cup per serving. For $22$ servings, the sugar needed is $22 \\times \\frac{1}{8} = \\frac{22}{8} = \\frac{11}{4}$ cups. Equivalently, setting up the proportion $\\frac{7/4}{14} = \\frac{x}{22}$ and cross-multiplying gives $14x = \\frac{7}{4} \\times 22 = \\frac{154}{4}$, so $x = \\frac{154}{56} = \\frac{11}{4}$. A common error is computing $\\frac{22}{14} \\approx 1.57$ and reporting that value instead of multiplying by the original sugar amount.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NP6AG0', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A chemist mixes Solution X, which is $20\\%$ acid, with Solution Y, which is $50\\%$ acid, to create $150$ milliliters of a mixture that is $38\\%$ acid. How many milliliters of Solution X does the chemist use?', NULL, $lyceon_json$[{"key":"A","text":"$45$"},{"key":"B","text":"$60$"},{"key":"C","text":"$75$"},{"key":"D","text":"$90$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $x$ be the volume of Solution X and $y$ the volume of Solution Y. The system is $x + y = 150$ and $0.20x + 0.50y = 0.38(150) = 57$. Substituting $y = 150 - x$ into the acid equation: $0.20x + 0.50(150 - x) = 57$, which simplifies to $0.20x + 75 - 0.50x = 57$, then $-0.30x = -18$, so $x = 60$. The value $45$ comes from computing the difference $0.50 - 0.38 = 0.12$ and multiplying by the total ($0.12 \\times 150 = 18$), then multiplying again by a factor of $2.5$ instead of using the full proportion — an incomplete line of reasoning. The value $75$ results from assuming each solution contributes equally ($150 \\div 2$), ignoring the concentration constraint entirely. The value $90$ is the amount of Solution Y, not Solution X, so selecting it reflects misreading which quantity the question asks for.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NXY2C1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'At a music festival, $41\\%$ of attendees are adults, $34\\%$ are teenagers, and the rest are children. Among adults, $67\\%$ bring their own water bottle. Among teenagers, $53\\%$ bring their own water bottle. Among children, $29\\%$ bring their own water bottle. If an attendee is selected at random and is found to have brought their own water bottle, what is the probability, to the nearest hundredth, that the attendee is a teenager?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '0.34', ARRAY['17/50', '0.34', '.34'], E'The percentage of children is $100\\% - 41\\% - 34\\% = 25\\%$. Using the law of total probability, the overall rate of bringing a water bottle is $P(W) = 0.41 \\times 0.67 + 0.34 \\times 0.53 + 0.25 \\times 0.29 = 0.2747 + 0.1802 + 0.0725 = 0.5274$. By Bayes'' theorem, $P(\\text{teenager} \\mid W) = \\frac{0.34 \\times 0.53}{0.5274} = \\frac{0.1802}{0.5274} \\approx 0.3417$, which rounds to $0.34$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ONMQ4N', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the equation of the line that passes through the points $(1, 9)$ and $(4, -3)$?', NULL, $lyceon_json$[{"key":"A","text":"$y = -12x + 21$"},{"key":"B","text":"$y = -4x - 13$"},{"key":"C","text":"$y = -4x + 13$"},{"key":"D","text":"$y = 4x + 5$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope is $\\frac{-3 - 9}{4 - 1} = \\frac{-12}{3} = -4$. Using point-slope form with $(1, 9)$: $y - 9 = -4(x - 1)$, so $y = -4x + 4 + 9 = -4x + 13$. The distractor $y = -12x + 21$ comes from using the rise $-12$ directly as the slope without dividing by the run, then computing $b = 9 - (-12)(1) = 21$. The distractor $y = -4x - 13$ results from a sign error computing the $y$-intercept as $4 - 9 = -13$ instead of $4 + 9 = 13$ when rearranging $y = -4x + (9 + 4)$. The distractor $y = 4x + 5$ arises from dropping the negative sign on the slope, computing $m = 4$, then $b = 9 - 4(1) = 5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QZS1WX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A swimming pool has the shape of a rectangular prism. It is $19$ meters long and $8$ meters wide. The pool is filled with water to a depth of $2$ meters. If $38$ cubic meters of water are added to the pool, by how many meters does the water level rise?', NULL, $lyceon_json$[{"key":"A","text":"$0.25$"},{"key":"B","text":"$0.5$"},{"key":"C","text":"$1$"},{"key":"D","text":"$2$"}]$lyceon_json$::jsonb, 'A', NULL, E'When water is added to a rectangular prism pool, the rise in water level $\\Delta h$ satisfies $V_{\\text{added}} = \\text{length} \\times \\text{width} \\times \\Delta h$. Therefore $38 = 19 \\times 8 \\times \\Delta h = 152 \\, \\Delta h$, giving $\\Delta h = \\frac{38}{152} = 0.25$ meters. The value $0.5$ results from dividing $38$ by only $19 \\times 4$, incorrectly halving one dimension. The value $1$ comes from dividing the added volume by the product of the length and the current depth: $\\frac{38}{19 \\times 2} = 1$, using the wrong pair of dimensions. The value $2$ equals the original depth, confusing the rise with the total depth.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ROEA8R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A car travels part of a $207$-mile trip at $54$ miles per hour and the remaining distance at $36$ miles per hour. If the entire trip takes $4.5$ hours, how many miles does the car travel at $54$ miles per hour?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$108$"},{"key":"C","text":"$135$"},{"key":"D","text":"$162$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $t$ be the time in hours spent driving at $54$ mph. The distance at $54$ mph is $54t$, and the distance at $36$ mph is $36(4.5 - t)$. Setting the total distance equal to $207$: $54t + 36(4.5 - t) = 207$, which simplifies to $54t + 162 - 36t = 207$, giving $18t = 45$ and $t = 2.5$ hours. The distance at $54$ mph is $54 \\times 2.5 = 135$ miles. The distractor $72$ equals $207 - 135 = 72$, which is the distance traveled at $36$ mph, not at $54$ mph. The distractor $108$ results from using $t = 2$ instead of $t = 2.5$, an arithmetic error when solving for $t$. The distractor $162$ results from computing $36 \\times 4.5 = 162$, applying the slower speed to the entire trip time.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RV1XGT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'For what value of $k$ does the system of equations $y = 3x^2 + 7x + k$ and $y = 5x - 2$ have exactly one real solution?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-5/3', ARRAY['-5/3', '-1.666', '-1.667'], E'Setting the equations equal gives $3x^2 + 7x + k = 5x - 2$, which rearranges to $3x^2 + 2x + (k + 2) = 0$. For this quadratic to have exactly one real solution, its discriminant must equal zero. The discriminant is $(2)^2 - 4(3)(k + 2) = 4 - 12(k + 2) = 4 - 12k - 24 = -20 - 12k$. Setting $-20 - 12k = 0$ gives $k = -\\frac{20}{12} = -\\frac{5}{3}$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SJRAHO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples were drawn from the same large population. Sample A consisted of $180$ respondents and yielded a sample proportion of $0.39$ with a margin of error of $\\pm 0.07$. Sample B consisted of $720$ respondents and yielded a sample proportion of $0.44$ with a margin of error of $\\pm 0.035$. Which of the following is the best conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The results contradict each other because the sample proportions differ by $0.05$."},{"key":"B","text":"Sample A is more trustworthy because smaller samples are less susceptible to outliers."},{"key":"C","text":"The results are consistent because the confidence intervals overlap, and Sample B provides a more precise estimate due to its larger size."},{"key":"D","text":"Neither result is useful because neither sample includes at least $1{,}000$ respondents."}]$lyceon_json$::jsonb, 'C', NULL, E'Sample A has a confidence interval of $[0.32, 0.46]$ and Sample B has a confidence interval of $[0.405, 0.475]$. These intervals overlap in the range $[0.405, 0.46]$, so the results are consistent with natural sampling variability. The larger sample ($720$ respondents) produces a smaller margin of error and thus a more precise estimate. The distractor claiming contradiction because proportions differ by $0.05$ confuses sampling variability with inconsistency. The distractor favoring the smaller sample reverses the relationship between sample size and precision. The distractor requiring $1{,}000$ respondents imposes an arbitrary threshold that has no statistical basis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VAO4LX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist records the population of bacteria (in thousands) at various hours after the start of an experiment.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VRB5KI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains $11$ peppermint candies, $7$ butterscotch candies, and $5$ cinnamon candies. If one candy is selected at random, what is the probability that it is a butterscotch candy?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{18}$"},{"key":"B","text":"$\\frac{7}{23}$"},{"key":"C","text":"$\\frac{5}{23}$"},{"key":"D","text":"$\\frac{7}{11}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of candies is $11 + 7 + 5 = 23$. The probability of selecting a butterscotch candy is the number of butterscotch candies divided by the total: $\\frac{7}{23}$. The distractor $\\frac{7}{18}$ divides by an incorrect total obtained from miscounting ($18$ instead of $23$). The distractor $\\frac{5}{23}$ uses the cinnamon count in the numerator instead of the butterscotch count. The distractor $\\frac{7}{11}$ divides by the peppermint count instead of the total number of candies.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
