INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WYEND4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'A function $f$ is defined by $f(x) = a \\cdot b^x + d$, where $a$, $b$, and $d$ are positive constants. It is known that $f(0) = 18$, $f(1) = 40$, and as $x$ decreases without bound, $f(x)$ approaches $7$. What is the value of $b$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$\\frac{20}{9}$"},{"key":"C","text":"$11$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'As $x$ decreases without bound, $b^x \\to 0$ (since $b > 0$ and $b \\neq 1$), so $f(x) \\to d$. Since $f(x)$ approaches $7$, $d = 7$. Using $f(0) = a \\cdot b^0 + 7 = a + 7 = 18$ gives $a = 11$. Then $f(1) = 11b + 7 = 40$ gives $11b = 33$, so $b = 3$. The distractor $\\frac{20}{9}$ results from ignoring $d$ and computing $\\frac{f(1)}{f(0)} = \\frac{40}{18} = \\frac{20}{9}$, as though $f(x) = a \\cdot b^x$ with no vertical shift. The distractor $11$ results from finding the value of $a$ and reporting it as $b$. The distractor $7$ results from confusing the asymptote value $d$ with the base $b$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X4RAHR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university study followed $950$ adults over $7$ years and found that those who read for more than $3$ hours per week had $27\\%$ lower rates of cognitive decline than those who read for fewer than $30$ minutes per week. A magazine concluded that reading prevents cognitive decline. Which of the following is the most valid criticism of the magazine''s conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The study's sample of $950$ adults is too small to detect a $27\\%$ difference."},{"key":"B","text":"The study was observational, so confounding variables such as education level or overall health habits may account for the association, and a causal claim is not justified."},{"key":"C","text":"The study should have included participants under $18$ years old to be valid."},{"key":"D","text":"The conclusion is valid because tracking participants over $7$ years ensures accuracy."}]$lyceon_json$::jsonb, 'B', NULL, E'The study tracked adults without randomly assigning them to reading groups, making it observational. Observational studies can identify associations but cannot establish causation because confounding variables — such as education level, socioeconomic status, or overall health habits — may explain the observed difference. The criticism that the sample size is too small is not well-founded, since $950$ adults over $7$ years is a substantial longitudinal dataset. The suggestion to include participants under $18$ addresses a different research question and does not resolve the causation issue. The claim that a long tracking period ensures accuracy confuses data collection duration with the ability to draw causal conclusions from an observational design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X7WFB5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A set of $9$ values has a mean of $34$. When two additional values, $47$ and $43$, are included, what is the mean of the new set of $11$ values?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '36', ARRAY['36'], E'The sum of the original $9$ values is $9 \\times 34 = 306$. Adding $47$ and $43$ gives a new sum of $306 + 47 + 43 = 396$. The mean of all $11$ values is $\\frac{396}{11} = 36$. A common error is averaging only the two new values with the old mean, computing $\\frac{34 + 47 + 43}{3} \\approx 41.3$, which ignores the weighting of the original nine values. Another error is dividing the new sum by $9$ instead of $11$, giving $\\frac{396}{9} = 44$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XXVNK7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'At what points do the graphs of $y = x^2 - 7x + 5$ and $y = x - 7$ intersect in the $xy$-plane?', NULL, $lyceon_json$[{"key":"A","text":"$(2, -5)$ and $(6, -1)$"},{"key":"B","text":"$(2, 5)$ and $(6, 1)$"},{"key":"C","text":"$(3, -4)$ and $(4, -3)$"},{"key":"D","text":"$(2, -5)$ only"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the expressions equal: $x^2 - 7x + 5 = x - 7$, which simplifies to $x^2 - 8x + 12 = 0$. Factoring gives $(x - 2)(x - 6) = 0$, so $x = 2$ or $x = 6$. Substituting into $y = x - 7$: when $x = 2$, $y = -5$; when $x = 6$, $y = -1$. The intersection points are $(2, -5)$ and $(6, -1)$. The distractor $(2, 5)$ and $(6, 1)$ results from dropping the negative signs when computing the $y$-values. The distractor $(3, -4)$ and $(4, -3)$ results from failing to subtract the $x$ term from both sides, getting $x^2 - 7x + 12 = 0$ instead, which factors as $(x - 3)(x - 4) = 0$. The distractor listing only $(2, -5)$ results from finding just one of the two solutions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y5WBTC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer produces $57$ pages in $3$ minutes. At this constant rate, how many pages does the printer produce in $11$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$171$"},{"key":"B","text":"$190$"},{"key":"C","text":"$209$"},{"key":"D","text":"$228$"}]$lyceon_json$::jsonb, 'C', NULL, E'The printer''s rate is $\\frac{57}{3} = 19$ pages per minute. In $11$ minutes, the printer produces $19 \\times 11 = 209$ pages. The distractor $171$ results from incorrectly computing $57 \\times 3$ rather than finding the unit rate and scaling. The distractor $190$ comes from multiplying $19 \\times 10$, stopping one minute short. The distractor $228$ results from computing $19 \\times 12$, using the wrong time value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YD52O1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A clinical trial tested a new sleep aid by randomly assigning $400$ volunteers to receive the sleep aid and $400$ to receive a placebo. The study found that the sleep aid group fell asleep an average of $19$ minutes faster than the placebo group, with $p < 0.02$. However, the sleep aid pills were noticeably larger and a different color than the placebo pills, and $81\\%$ of participants in the sleep aid group correctly identified that they were receiving the active treatment. Which of the following best describes a limitation of this study?', NULL, $lyceon_json$[{"key":"A","text":"The $p$-value of less than $0.02$ indicates the results are not statistically significant, so no conclusion can be drawn."},{"key":"B","text":"The study lacks a control group because the placebo was visually different from the sleep aid."},{"key":"C","text":"Participants' ability to identify their treatment may have introduced expectation bias, undermining the blinding and potentially inflating the observed benefit."},{"key":"D","text":"A sample of $800$ total participants is too small to detect a $19$-minute difference in sleep onset."}]$lyceon_json$::jsonb, 'C', NULL, E'Although this was a randomized controlled experiment, effective blinding requires that participants cannot distinguish the treatment from the placebo. Because the pills differed in size and color, $81\\%$ of participants in the sleep aid group correctly identified their assignment. This compromised blinding can introduce expectation bias: participants who believe they received the active treatment may perceive faster sleep onset regardless of the pill''s actual effect, inflating the observed $19$-minute advantage. The claim that $p < 0.02$ is not statistically significant misinterprets the $p$-value, since $0.02$ is below the conventional $0.05$ threshold. The claim that there is no control group is incorrect because the placebo group serves as the control regardless of visual differences. The claim that $800$ participants is too small is unfounded, as the study detected a statistically significant effect with this sample.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YP5JVG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'grid_in', E'A circle has a circumference of $34\\pi$ centimeters. What is the diameter, in centimeters, of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '34', ARRAY['34'], E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Setting $\\pi d = 34\\pi$ and dividing both sides by $\\pi$ gives $d = 34$ centimeters. A common error is to confuse diameter and radius, dividing by $2$ to get $17$. Another error is to use the area formula $A = \\pi r^2$ instead of the circumference formula, which leads to an entirely different calculation.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YZ1WE5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $23$ inches and a width of $9$ inches. What is the area, in square inches, of the rectangle?', NULL, $lyceon_json$[{"key":"A","text":"$64$"},{"key":"B","text":"$161$"},{"key":"C","text":"$207$"},{"key":"D","text":"$414$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is $A = \\text{length} \\times \\text{width} = 23 \\times 9 = 207$ square inches. The value $64$ comes from computing the perimeter $2(23 + 9) = 64$ instead of the area. The value $161$ results from a multiplication error such as $23 \\times 7 = 161$. The value $414$ doubles the correct area, as if computing $2 \\times 23 \\times 9$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z7YFL9', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(5x + 3)(3x - 8)$?', NULL, $lyceon_json$[{"key":"A","text":"$15x^2 + 31x - 24$"},{"key":"B","text":"$15x^2 - 31x - 24$"},{"key":"C","text":"$15x^2 - 49x - 24$"},{"key":"D","text":"$15x^2 - 31x + 24$"}]$lyceon_json$::jsonb, 'B', NULL, E'Applying FOIL: $(5x)(3x) = 15x^2$, $(5x)(-8) = -40x$, $(3)(3x) = 9x$, and $(3)(-8) = -24$. Combining the middle terms gives $-40x + 9x = -31x$, so the product is $15x^2 - 31x - 24$. The distractor $15x^2 + 31x - 24$ arises from reversing the sign of the combined middle term. The distractor $15x^2 - 49x - 24$ arises from adding the magnitudes of the middle terms ($40 + 9 = 49$) instead of subtracting. The distractor $15x^2 - 31x + 24$ results from incorrectly treating the constant term $(-3)(8) = -24$ as positive.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZQEPIY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $4x^2 - 121 = 0$, what is the positive value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/2', ARRAY['11/2', '5.5'], E'Adding $121$ to both sides gives $4x^2 = 121$. Dividing both sides by $4$ gives $x^2 = \\frac{121}{4}$. Taking the square root of both sides gives $x = \\pm\\frac{11}{2}$. Since the question asks for the positive value, the answer is $\\frac{11}{2}$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20G7WXR', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Geochemist Amara Osei studied calcium carbonate deposits in 41 freshwater springs across the Appalachian Mountains and found that springs with higher dissolved carbon dioxide concentrations consistently produced thicker carbonate crusts on surrounding rock surfaces. Osei noted that when carbon dioxide-rich water reaches the surface and is exposed to air, the dissolved gas escapes rapidly, shifting the water''s chemical equilibrium and causing dissolved calcium carbonate to precipitate as a solid. She also observed that springs in densely forested ravines, where air circulation is restricted, produced notably thinner crusts than springs in open meadows at comparable elevations and carbon dioxide levels. Osei therefore proposed that the rate of crust formation depends not only on dissolved carbon dioxide concentration but also on ________', $lyceon_json$[{"key":"A","text":"how quickly carbon dioxide can escape from the water at the surface, which is influenced by local air circulation patterns."},{"key":"B","text":"the mineral composition of the bedrock through which the spring water travels before reaching the surface."},{"key":"C","text":"seasonal variations in water temperature that affect the solubility of calcium carbonate."},{"key":"D","text":"the presence of microbial communities that consume dissolved carbon dioxide before it can escape into the atmosphere."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that carbonate precipitation occurs when dissolved carbon dioxide escapes at the surface, and that springs in sheltered ravines with restricted air circulation produce thinner crusts than those in open meadows with similar carbon dioxide levels. The option about escape rate being influenced by air circulation logically completes the argument — restricted air movement slows gas escape, reducing precipitation. The option about bedrock mineral composition introduces a subsurface factor the passage does not discuss as a variable. The option about seasonal water temperature variations introduces a factor unmentioned in the passage. The option about microbial communities consuming carbon dioxide introduces an organism the passage never references.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21ME8RC', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a report about the history ofEli Whitney''s cotton gin for an American history class. The student wants to emphasize an unintended consequence of the cotton gin''s invention. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21W8I6Q', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Certain species of cleaner fish, such as the bluestreak cleaner wrasse, remove parasites from larger reef fish at designated cleaning stations. Marine biologist Henrik Larsson observed that when a cleaner wrasse occasionally bites a client fish to feed on its protective mucus instead of parasites, the client fish jolts away and avoids that particular cleaning station for several days. Larsson also found that cleaner wrasses that cheat more frequently receive fewer client visits over time. These patterns suggest that cleaner wrasses that cheat too often ________', $lyceon_json$[{"key":"A","text":"lose access to a reliable food source as client fish learn to avoid them."},{"key":"B","text":"develop a dietary preference for mucus over parasites as they age."},{"key":"C","text":"are expelled from cleaning stations by other cleaner wrasses."},{"key":"D","text":"attract a greater variety of client fish species than honest cleaners do."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that cheated client fish avoid the offending station and that frequent cheaters receive fewer visits. The option about losing access to a reliable food source follows logically — fewer clients means less food. The option about developing a mucus preference introduces a dietary shift the passage does not discuss. The option about expulsion by other wrasses introduces a social mechanism the passage never mentions. The option claiming cheaters attract more species directly contradicts the finding that frequent cheaters receive fewer client visits.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW224TV5N', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Urban archaeologist Seo-yeon Park contends that the conventional interpretation of Joseon-era stone walls in Seoul — as purely defensive fortifications — underestimates their role in managing seasonal flooding. Park''s analysis of 38 wall segments built between 1396 and 1450 reveals that drainage channels were integrated into the wall foundations at intervals matching the city''s natural watershed paths. Furthermore, sediment deposits found at these channel openings contain organic material consistent with agricultural runoff, suggesting the walls simultaneously redirected floodwater toward designated farmland outside the city perimeter.', $lyceon_json$[{"key":"A","text":"Park argues that Joseon-era stone walls in Seoul served a dual purpose, functioning not only as fortifications but also as a flood management infrastructure that channeled water toward agricultural land."},{"key":"B","text":"Park has proven that the Joseon-era walls in Seoul were never intended for military defense and were built exclusively for water management."},{"key":"C","text":"The agricultural practices of Joseon-era Seoul depended entirely on floodwater redirected through the city's stone walls."},{"key":"D","text":"Park discovered that the stone walls built between 1396 and 1450 had deteriorated beyond their original structural capacity by the end of the Joseon dynasty."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Park''s argument that Joseon-era walls, while conventionally viewed as defensive structures, also incorporated drainage features that managed flooding and directed water to farmland. The option describing a dual purpose — defense and flood management — accurately reflects this nuanced claim. The option asserting the walls were never intended for defense overstates Park''s position; she argues the conventional view underestimates an additional function, not that the defensive role was nonexistent. The option claiming agriculture depended entirely on redirected floodwater goes far beyond the passage, which merely notes evidence of agricultural runoff at the channels. The option about structural deterioration introduces a topic the passage never addresses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22D8T2I', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the calcium carbonate samples collected from the cave''s upper gallery nor the single stalactite fragment recovered from the _______ any detectable trace of the sulfate minerals that would indicate prolonged contact with acidic groundwater.', $lyceon_json$[{"key":"A","text":"lowest chamber contain"},{"key":"B","text":"lowest chamber contains"},{"key":"C","text":"lowest chambers contain"},{"key":"D","text":"lowest chambers contains"}]$lyceon_json$::jsonb, 'B', NULL, E'In a ''neither...nor'' construction, the verb agrees with the nearer subject. The nearer subject is ''the single stalactite fragment,'' which is singular, so the verb must be the singular ''contains.'' The option ''lowest chamber contains'' correctly pairs the singular noun ''chamber'' with the singular verb ''contains,'' maintaining agreement with the nearer singular subject. The option ''lowest chamber contain'' uses the singular noun but the plural verb ''contain,'' violating subject-verb agreement with the nearer subject. The option ''lowest chambers contain'' changes ''chamber'' to plural unnecessarily; while the plural verb would agree with a plural noun, the context describes a single lowest chamber, and more importantly the verb must agree with ''fragment,'' not ''chamber.'' The option ''lowest chambers contains'' pairs a plural noun with a singular verb, creating an internal disagreement regardless of the neither-nor rule.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22J3P06', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Musicologist Héctor Aguayo has argued that the charango, a small stringed instrument central to Andean folk _______ was likely adapted from the Spanish vihuela by indigenous musicians in the silver-mining town of Potosí during the late sixteenth century.', $lyceon_json$[{"key":"A","text":"music"},{"key":"B","text":"music,"},{"key":"C","text":"music;"},{"key":"D","text":"music—"}]$lyceon_json$::jsonb, 'B', NULL, E'The phrase ''a small stringed instrument central to Andean folk music'' is an appositive that renames ''the charango.'' This nonrestrictive appositive is introduced by a comma (before ''a small stringed instrument''), so it must be closed with a matching comma after ''music'' to return to the main clause (''was likely adapted...''). The option ''music,'' correctly closes the appositive with a comma. The option ''music'' omits the closing punctuation, leaving the appositive unclosed and creating a grammatically broken sentence. The option ''music;'' uses a semicolon, which would require two independent clauses; ''was likely adapted...'' is not an independent clause but continues the ''that'' clause begun earlier. The option ''music—'' would require a matching dash before the appositive rather than the comma already present, producing mismatched punctuation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23F4WMZ', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23S4VBC', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Urban planner Kwame Asante has proposed that the widespread adoption of reflective roofing materials in tropical megacities could reduce urban heat island effects by as much as 2.1 degrees Celsius during peak summer months. Asante''s computational models, which incorporate satellite thermal data from seventeen cities across South Asia and West Africa, show that neighborhoods with high concentrations of reflective roofs experience measurably lower ambient air temperatures than adjacent districts with conventional dark roofing. Critics have noted, however, that Asante''s models do not account for the increased glare and reflected solar radiation that could raise cooling costs in neighboring taller buildings. _______ the net energy savings may be smaller than Asante''s projections suggest once the secondary thermal effects on adjacent structures are factored into the calculation.', $lyceon_json$[{"key":"A","text":"That is,"},{"key":"B","text":"On the other hand,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Furthermore,"}]$lyceon_json$::jsonb, 'A', NULL, E'The critics have just raised a concern about unaccounted secondary effects (increased glare raising cooling costs in neighboring buildings). The sentence after the blank restates and clarifies that concern in more precise terms: the net energy savings may be smaller once secondary thermal effects are factored in. "That is," correctly signals a restatement or clarification of the critics'' point. "On the other hand," implies a shift to a contrasting perspective, but the sentence continues developing the same critical point rather than introducing an opposing view. "For instance," would introduce a specific example to illustrate a broader claim, but the sentence provides a summary reformulation rather than an illustrative case. "Furthermore," would add a new, separate point of criticism, but the sentence restates the same concern about secondary thermal effects in different terms rather than introducing an additional objection.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
