INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27RYD2L', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Davi Serpa has cataloged over four hundred species of weevils in the Brazilian cerrado. Among these, the acorn weevil Curculio glandium is notable for its unusually long rostrum, which the _______ to bore into the hard shells of baru nuts and deposit eggs inside the nutritious kernel.', $lyceon_json$[{"key":"A","text":"female is using"},{"key":"B","text":"female uses"},{"key":"C","text":"females, using"},{"key":"D","text":"female, using"}]$lyceon_json$::jsonb, 'B', NULL, E'The relative clause beginning with ''which'' requires a subject and a finite verb to form a complete clause: ''which the female uses to bore into...'' describes a habitual behavior. The option ''female uses'' correctly supplies the simple present tense, conveying the species'' characteristic behavior. The option ''female is using'' employs the present progressive, which implies an action currently in progress rather than a habitual trait of the species; for describing a general biological behavior, the simple present is the standard form. The option ''females, using'' introduces a plural noun that does not agree with the singular species description and replaces the finite verb with a participle, leaving the relative clause without a main verb. The option ''female, using'' inserts a comma and a participle rather than a finite verb, which leaves the ''which'' clause incomplete—''which the female'' has no predicate verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A4IC35', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "tempered" most nearly mean?', E'Chef Inara Mboleko, who trained in classical French technique before opening a restaurant in Maputo, has tempered her approach to pastry by incorporating cassava flour and tamarind into recipes that traditionally call for wheat and citrus. Critics note that this blend of European precision and Mozambican ingredients produces desserts unlike anything found on either continent.', $lyceon_json$[{"key":"A","text":"moderated"},{"key":"B","text":"heated"},{"key":"C","text":"enraged"},{"key":"D","text":"constructed"}]$lyceon_json$::jsonb, 'A', NULL, E'In the passage, "tempered" describes how Mboleko adjusted or moderated her pastry approach by blending ingredients from two traditions, making "moderated" the correct choice. "Heated" refers to raising temperature, a metallurgical or culinary meaning of "temper" that does not fit the context of adjusting a creative methodology. "Enraged" means to make furious, which is unrelated to the act of adapting a cooking approach. "Constructed" means to build or assemble, which does not convey the sense of softening or adjusting an existing method.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AAKPJL', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ceramic workshops of ancient Jingdezhen produced porcelain of extraordinary refinement. Artisans in these workshops used a locally sourced mineral called petuntse to achieve the translucent _______ distinguished Jingdezhen ware from the opaque stoneware produced in other regions of imperial China.', $lyceon_json$[{"key":"A","text":"quality, that"},{"key":"B","text":"quality that"},{"key":"C","text":"quality. That"},{"key":"D","text":"quality; that"}]$lyceon_json$::jsonb, 'B', NULL, E'The word ''that'' introduces a restrictive relative clause identifying which quality is meant. Restrictive relative clauses beginning with ''that'' are not set off by punctuation. The option ''quality that'' correctly joins the noun to its restrictive clause without intervening punctuation. The option ''quality, that'' inserts an unnecessary comma before a restrictive ''that'' clause, treating it as nonrestrictive, which is not standard with ''that.'' The option ''quality. That'' creates a sentence fragment because ''That distinguished Jingdezhen ware...'' lacks an independent subject-verb structure when severed from its antecedent. The option ''quality; that'' similarly severs the restrictive clause from the noun it modifies, and the text following the semicolon does not form an independent clause.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AJ9ACZ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a short informational piece about the kakapo for a wildlife conservation newsletter. The student wants to introduce the kakapo to readers who may not know what it is. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AW1MKQ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economist Tariq al-Mansur analyzed wage data from 11 European countries that implemented national minimum wage increases of at least 15 percent between 2010 and 2019. In each case, opponents had predicted significant job losses in low-wage sectors such as hospitality and retail. Al-Mansur found that employment in these sectors remained stable or grew modestly in nine of the eleven countries. However, he also discovered that in those same nine countries, the average number of hours worked per employee in affected sectors declined by 7 to 11 percent within two years of the wage increase. Al-Mansur cautioned that these findings complicate the standard debate, because they suggest that employers responded to higher minimum wages not primarily by eliminating positions but rather by ________', $lyceon_json$[{"key":"A","text":"reducing the hours allocated to each worker, thereby preserving employment headcounts while still lowering total labor costs."},{"key":"B","text":"shifting their business operations to countries with lower labor costs to maintain profit margins."},{"key":"C","text":"investing in employee training programs that increased worker productivity enough to offset the higher wages entirely."},{"key":"D","text":"passing the increased labor costs directly to consumers through uniform price increases across all product categories."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that employment levels held steady but hours per employee declined by 7 to 11 percent after minimum wage increases. The option about reducing hours per worker to preserve headcounts while lowering total labor costs logically follows from these two data points — employers maintained staff numbers but cut hours, which the passage frames as complicating the standard debate about job losses. The option about relocating operations to other countries introduces a response the passage does not mention and that would be inconsistent with stable domestic employment. The option about training programs offsetting costs introduces an employer strategy the passage never discusses. The option about uniform consumer price increases introduces a mechanism the passage does not address and makes an unsupported claim about uniformity across product categories.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BKI3V6', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Literary historian Margaux Tessier has argued that the French novelist Émile Zola''s decision to serialize his novels in daily newspapers was not merely a commercial strategy but a deliberate aesthetic choice. Zola, Tessier contends, structured his narratives around short, suspenseful installments precisely because the daily publication rhythm forced readers to sit with unresolved tensions overnight, amplifying the emotional impact of his social critiques. Other scholars have objected that Zola''s private correspondence reveals frequent complaints about the constraints of serialization, suggesting he viewed the format as an economic necessity rather than an artistic tool. _______ Tessier has acknowledged the complaints but maintains that dissatisfaction with practical constraints does not preclude strategic exploitation of the format''s unique rhetorical possibilities.', $lyceon_json$[{"key":"A","text":"In response,"},{"key":"B","text":"Likewise,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents an academic disagreement: Tessier advances a thesis, other scholars challenge it with counter-evidence from Zola''s correspondence, and the sentence after the blank shows Tessier reacting to that challenge with a partial concession and a rebuttal. "In response," correctly signals that Tessier is directly replying to the objection raised by other scholars. "Likewise," implies a parallel or agreement between two ideas, but Tessier is not agreeing with the critics — she is acknowledging their evidence while defending her position. "Specifically," would introduce a narrowing detail or example, but the sentence instead shifts the argumentative dynamic by addressing the critics'' counter-evidence. "Consequently," implies that Tessier''s acknowledgment is a causal result of the critics'' objection in a logical-deductive sense, but the sentence describes a dialogic reply, not a logical consequence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EXNUWB', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geographer Tomoko Iida has shown that the terraced rice paddies of the Philippine Cordilleras, constructed by the Ifugao people over two thousand years ago, function as a remarkably sophisticated water management system. Stone-lined channels distribute water from mountaintop forests downhill through hundreds of individually flooded terraces, maintaining consistent moisture levels without mechanical pumps. _______ the same channel network also serves a critical ecological role, sustaining freshwater snail populations and aquatic invertebrates that provide natural pest control for the rice crops.', $lyceon_json$[{"key":"A","text":"Consequently,"},{"key":"B","text":"However,"},{"key":"C","text":"In addition,"},{"key":"D","text":"Instead,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first describes one function of the channel network — water distribution for rice cultivation. The sentence after the blank introduces a second, separate function of the same network: sustaining organisms that provide natural pest control. "In addition," correctly signals that a supplementary point is being added about a different benefit of the channel system. "Consequently," would imply that the ecological role is a direct result of the water management function, but the sentence presents the ecological role as an independent benefit rather than a causal outcome. "However," introduces a contrast or concession, yet the ecological function does not contradict the water management function. "Instead," implies substitution or replacement, but the pest-control role does not replace the irrigation role — both coexist.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F8QG9E', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if accurate, would most directly challenge the conclusion described in the text?', E'Transportation engineer Kwame Asante analyzed ridership data from 19 North American cities that replaced fixed bus routes with on-demand microtransit services between 2017 and 2022. Asante concluded that on-demand microtransit consistently failed to match the ridership levels of the fixed routes it replaced, citing an average 34 percent decline in total boardings within two years of the switch. He attributed this decline primarily to the fact that on-demand scheduling introduces wait-time unpredictability, which discourages habitual riders who depend on consistent commute timing.', $lyceon_json$[{"key":"A","text":"Three cities that implemented on-demand microtransit with guaranteed maximum wait times of eight minutes experienced ridership increases of 12 percent over the same two-year period."},{"key":"B","text":"On-demand microtransit vehicles consume 20 percent less fuel per passenger-mile than traditional fixed-route buses."},{"key":"C","text":"Cities that maintained fixed bus routes during the same period experienced stable ridership levels overall."},{"key":"D","text":"Riders who used on-demand microtransit reported higher satisfaction with vehicle cleanliness compared to riders of fixed-route buses."}]$lyceon_json$::jsonb, 'A', NULL, E'Asante concludes that microtransit fails to match fixed-route ridership because wait-time unpredictability deters habitual riders. The finding that cities guaranteeing short maximum wait times actually saw ridership increases directly undermines his conclusion by showing that when the proposed mechanism — unpredictability — is addressed, ridership does not decline. The finding about fuel efficiency concerns operational cost, not ridership levels. The finding about stable ridership on maintained fixed routes is consistent with Asante''s conclusion rather than challenging it. The finding about vehicle cleanliness satisfaction addresses rider experience on a dimension unrelated to ridership volume or wait-time predictability.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H7DUP3', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes how the author of Text 2 would most likely evaluate the approach described in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HY3QMY', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the board of the Tillman County Historical Society reviewed proposals for restoring the 1893 courthouse, members disagreed about whether _______ original cedar shingles or replace them with modern composite tiles that would require less maintenance.', $lyceon_json$[{"key":"A","text":"to preserve its"},{"key":"B","text":"to preserve their"},{"key":"C","text":"preserving its"},{"key":"D","text":"preserving their"}]$lyceon_json$::jsonb, 'A', NULL, E'The construction ''disagreed about whether... or replace'' requires parallel infinitive forms: ''whether to preserve... or replace.'' The possessive pronoun must refer to the singular antecedent ''the 1893 courthouse,'' so the singular ''its'' is correct. The option ''to preserve its'' correctly supplies the infinitive and the singular possessive. The option ''to preserve their'' uses the correct infinitive form but the plural pronoun ''their,'' which does not agree with the singular antecedent ''courthouse.'' The option ''preserving its'' uses a gerund form that is not parallel with ''replace'' in the ''whether... or replace'' construction and breaks the expected infinitive parallelism. The option ''preserving their'' combines the non-parallel gerund form with the incorrect plural pronoun.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I7JYG4', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Musicologist Radhika Venkataraman challenges the widespread characterization of Carnatic music improvisation as spontaneous creativity operating within rigid raga frameworks. Venkataraman''s corpus analysis of 146 recorded performances by vocalist M. S. Subbulakshmi reveals that approximately 70 percent of passages classified as improvised by contemporary critics consist of recombined melodic phrases Subbulakshmi had employed in earlier performances. Venkataraman stops short of calling these passages formulaic, however, noting that the recombinations themselves follow no predictable sequence and that Subbulakshmi frequently modified the rhythmic placement of familiar phrases to create novel aesthetic effects. Venkataraman proposes that this practice constitutes a distinct mode of creativity — one that is neither fully spontaneous nor merely reproductive but operates through the strategic recontextualization of a personal repertoire of melodic material.', $lyceon_json$[{"key":"A","text":"Venkataraman argues that Carnatic improvisation, rather than being either spontaneous or formulaic, involves a distinctive creative process of strategically recombining and recontextualizing previously used melodic material."},{"key":"B","text":"Venkataraman demonstrates that M. S. Subbulakshmi's performances lacked genuine improvisation because most of her melodic passages were borrowed from earlier recordings."},{"key":"C","text":"Venkataraman proposes that the raga framework in Carnatic music is more flexible than most musicologists have recognized."},{"key":"D","text":"Venkataraman's corpus analysis proves that contemporary music critics are unreliable judges of improvisation in Carnatic vocal performance."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Venkataraman''s argument that Carnatic improvisation is neither fully spontaneous nor merely reproductive, characterizing it instead as strategic recontextualization of familiar melodic material. The option describing this distinct creative mode of recombining and recontextualizing captures the nuanced thesis. The option claiming Subbulakshmi lacked genuine improvisation contradicts the passage — Venkataraman explicitly avoids calling the passages formulaic and identifies novel aesthetic effects in their rhythmic redeployment. The option about raga framework flexibility addresses a tangential topic; Venkataraman''s argument concerns the nature of the improvisation itself, not the rigidity of the raga system. The option about critics being unreliable overstates a minor detail — the passage notes that critics classified certain passages as improvised, but Venkataraman''s point is about the nature of improvisation, not about critical competence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KZYCRQ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After analyzing satellite imagery collected over fourteen months, geologist Renata Voss determined that the glacier''s retreat had accelerated _______ she recommended that the regional conservation authority expand its monitoring program to include quarterly aerial surveys.', $lyceon_json$[{"key":"A","text":"significantly, and"},{"key":"B","text":"significantly and"},{"key":"C","text":"significantly, and,"},{"key":"D","text":"significantly and,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence contains two independent clauses joined by the coordinating conjunction ''and.'' When two independent clauses are joined by a FANBOYS conjunction, a comma must precede the conjunction. The option ''significantly, and'' correctly places a comma before ''and'' to separate the two independent clauses. The option ''significantly and'' omits the required comma before a coordinating conjunction joining two independent clauses. The option ''significantly, and,'' adds an unnecessary comma after ''and,'' incorrectly separating the conjunction from the clause it introduces. The option ''significantly and,'' omits the comma before the conjunction while adding a spurious comma after it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L25TG2', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the primary purpose of the text?', E'Architectural historian Elif Bayraktar has challenged the prevailing interpretation of Ottoman-era caravanserais as purely commercial infrastructure. Examining masonry inscriptions and endowment deeds from seventeen caravanserais constructed between 1453 and 1620, Bayraktar demonstrates that their founders frequently dedicated these structures as pious endowments (waqf), stipulating that revenues fund mosques, soup kitchens, and schools in distant provinces. She contends that this philanthropic function was not incidental but architecturally encoded: the monumental portals, carved prayer niches, and calligraphic programs adorning these buildings communicated charitable purpose to travelers and townsfolk alike, situating the caravanserai within a network of religious obligation rather than merely commercial convenience.', $lyceon_json$[{"key":"A","text":"To present a scholar's argument that a class of historical buildings served a religious and charitable function that existing scholarship has undervalued."},{"key":"B","text":"To catalog the architectural features common to Ottoman caravanserais built during the fifteenth and sixteenth centuries."},{"key":"C","text":"To trace how the commercial role of caravanserais evolved over the course of the Ottoman Empire's expansion."},{"key":"D","text":"To compare Bayraktar's archaeological methods with those used by earlier historians of Ottoman architecture."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Bayraktar''s argument that caravanserais were architecturally encoded as pious endowments, challenging the prevailing view that treats them as purely commercial, so the choice about presenting a scholar''s argument that a charitable function has been undervalued is correct. The choice about cataloging architectural features is wrong because the passage mentions portals, prayer niches, and calligraphy only as evidence supporting Bayraktar''s interpretive claim, not as the primary purpose of the text. The choice about tracing commercial evolution is wrong because the passage does not track how commercial function changed over time but instead argues that a non-commercial function has been overlooked. The choice about comparing archaeological methods is wrong because the passage does not discuss or contrast the methodologies of different historians.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LS5WET', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'During the 1970s, Soviet glaciologists proposed that Lake Vostok, buried beneath nearly four kilometers of Antarctic ice, might harbor liquid water kept from freezing by geothermal heat and the insulating pressure of the overlying ice sheet. This hypothesis remained speculative until 1996, when airborne radar surveys confirmed the presence of a subglacial lake roughly the size of Lake Ontario. Subsequent seismic analyses revealed that the lake floor sits in a geological rift zone, supporting the original thermal model. Yet the most consequential discovery came in 2012, when a Russian drilling team breached the lake surface and retrieved water samples containing trace DNA sequences — raising the possibility that microbial life persists in one of Earth''s most isolated environments.', $lyceon_json$[{"key":"A","text":"It presents a hypothesis, describes the evidence that progressively confirmed it, and concludes with a discovery that expanded the hypothesis's implications."},{"key":"B","text":"It compares two rival theories about subglacial lakes and evaluates which has stronger evidential support."},{"key":"C","text":"It narrates a single experiment from its design phase through its results and then critiques its methodology."},{"key":"D","text":"It defines a geological phenomenon and then catalogs the different locations where that phenomenon has been observed."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first introduces the Soviet hypothesis about liquid water beneath the ice, then traces successive confirmations (radar in 1996, seismic analysis of the rift zone), and concludes with the 2012 DNA discovery that expanded the hypothesis beyond geology into biology — matching the choice about presenting a hypothesis, progressive confirmation, and an implication-expanding discovery. The choice about comparing rival theories is wrong because the passage presents only one hypothesis and does not introduce a competing explanation. The choice about narrating a single experiment is wrong because the passage spans multiple investigations over four decades rather than detailing one experiment''s design and methodology. The choice about cataloging different locations is wrong because the passage discusses only Lake Vostok rather than surveying multiple subglacial sites.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NY8AW4', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'At the Reykjavik Maritime Museum, a restored fishing trawler from 1951 _______ visitors a firsthand look at the working conditions endured by Icelandic cod fishermen during the mid-twentieth century.', $lyceon_json$[{"key":"A","text":"offer"},{"key":"B","text":"offering"},{"key":"C","text":"offers"},{"key":"D","text":"have offered"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is ''a restored fishing trawler from 1951,'' which is singular and requires a singular verb in the simple present tense. The option ''offers'' is the correct third-person singular present-tense form. The option ''offer'' is a bare plural form that does not agree with the singular subject. The option ''offering'' is a participle, not a finite verb, and would leave the sentence without a main verb. The option ''have offered'' uses the plural auxiliary ''have,'' which does not agree with the singular subject ''a restored fishing trawler.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OOPOKH', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is drafting a research brief about muon tomography for a physics seminar. The student wants to explain how the technique works while also noting a specific limitation that affects its practical use. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QLB1S8', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a published study would, if included in the text, most effectively serve as evidence supporting Nakamura''s argument?', E'Cognitive scientist Yuki Nakamura argues that bilingual children do not simply switch between two separate linguistic systems but instead develop an integrated cognitive architecture in which both languages continuously influence each other at the level of phonological processing. Nakamura contends that this cross-linguistic interaction, far from being a source of confusion, actually sharpens bilingual children''s sensitivity to sound contrasts that monolingual children in either language tend to overlook. She predicts that this enhanced phonological sensitivity should be detectable even when bilingual children are tested exclusively in one of their two languages.', $lyceon_json$[{"key":"A","text":"\"Bilingual children aged five to seven identified phonemic contrasts in their dominant language with 23 percent greater accuracy than age-matched monolingual peers, even when no stimuli from their second language were present during testing.\""},{"key":"B","text":"\"Monolingual children exposed to a second language for six weeks showed temporary improvements in vocabulary acquisition but no lasting gains in phonological discrimination.\""},{"key":"C","text":"\"Bilingual adults who acquired their second language after age twelve performed equivalently to monolinguals on all measures of phonological awareness.\""},{"key":"D","text":"\"Children enrolled in dual-language immersion programs scored higher on standardized reading comprehension tests than children in monolingual classrooms.\""}]$lyceon_json$::jsonb, 'A', NULL, E'Nakamura argues that bilingual children develop enhanced phonological sensitivity due to cross-linguistic interaction, detectable even in single-language testing. The quotation showing bilingual children identified phonemic contrasts with greater accuracy than monolinguals in a single-language testing environment directly supports both the claim of enhanced sensitivity and Nakamura''s prediction about single-language detectability. The quotation about monolingual children briefly exposed to a second language concerns a different population and short-term vocabulary effects, not the integrated phonological architecture Nakamura describes. The quotation about late-acquisition bilingual adults addresses a different age group and acquisition timeline, which Nakamura''s argument about developmental cognitive architecture does not encompass. The quotation about reading comprehension scores measures a different cognitive skill entirely and does not address phonological sensitivity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R0Q8PU', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By analyzing pollen samples extracted from sediment cores drilled at twelve sites along the ancient lakebed and cross-referencing those samples with radiocarbon dates obtained from charcoal fragments embedded in the same _______ the paleoecologist reconstructed a continuous record of vegetation change spanning eight thousand years.', $lyceon_json$[{"key":"A","text":"strata,"},{"key":"B","text":"strata;"},{"key":"C","text":"strata."},{"key":"D","text":"strata"}]$lyceon_json$::jsonb, 'A', NULL, E'The entire construction from ''By analyzing'' through ''strata'' is an introductory participial phrase modifying the subject ''the paleoecologist.'' Standard English requires a comma after an introductory dependent phrase before the independent clause that follows. The option placing a comma after ''strata'' correctly marks this boundary. The option using a semicolon is wrong because a semicolon requires two independent clauses on either side, and ''By analyzing...strata'' is not an independent clause — it lacks a subject performing a main action. The option using a period is wrong because ''By analyzing pollen samples...strata.'' is a sentence fragment: the ''By'' phrase has no main clause to complete it. The option with no punctuation is wrong because omitting the comma after a long introductory phrase creates a run-on construction that obscures where the modifying phrase ends and the main clause begins.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RZFF08', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "elastic" most nearly mean?', E'Political scientist Kwame Adjei has observed that voter allegiance in Ghana''s Fourth Republic is more elastic than conventional models of partisan loyalty predict. His analysis of polling data from seven consecutive election cycles reveals that roughly 29 percent of voters in the Ashanti Region shifted party preference at least once, a finding that contradicts the widespread assumption that voting patterns in the region are permanently fixed along ethnic lines.', $lyceon_json$[{"key":"A","text":"flexible"},{"key":"B","text":"rubbery"},{"key":"C","text":"exhausting"},{"key":"D","text":"circular"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage uses "elastic" to describe voter allegiance that is capable of changing rather than remaining fixed, making "flexible" the correct meaning. "Rubbery" describes a physical material property and cannot coherently describe political allegiance. "Exhausting" means tiring or draining, which has no connection to the concept of changeable loyalty. "Circular" means moving in a loop or returning to a starting point, which does not capture the idea of allegiance being subject to change.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SQ4V4N', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The red-billed oxpecker perches on the hides of large African mammals and feeds on ticks and other parasites. For decades, ecologists classified this relationship as mutualistic, assuming the birds benefit their hosts by removing harmful organisms. _However, a 2019 study by ornithologist Samuel Moteki found that oxpeckers also feed on the blood that seeps from wounds on their hosts, sometimes enlarging existing injuries to increase blood flow._ This finding has prompted researchers to reconsider whether the oxpecker-host relationship is genuinely beneficial for both parties.', $lyceon_json$[{"key":"A","text":"It presents evidence that complicates a previously accepted characterization of a biological relationship."},{"key":"B","text":"It explains why ticks are harmful to large African mammals."},{"key":"C","text":"It describes the method ecologists use to classify species interactions."},{"key":"D","text":"It summarizes the consensus view among ornithologists about oxpecker behavior."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence introduces Moteki''s finding that oxpeckers also feed on host blood and enlarge wounds, which challenges the prior assumption that the relationship is purely mutualistic, so the choice about presenting evidence that complicates a previously accepted characterization is correct. The choice about explaining why ticks are harmful is wrong because the underlined sentence focuses on oxpecker behavior, not tick damage. The choice about describing classification methods is wrong because the sentence reports a specific finding rather than explaining an ecological methodology. The choice about summarizing consensus is wrong because the finding contradicts the established view rather than representing it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TMJOQ4', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'A team of entomologists at the University of Helsinki recently documented that wood ants in boreal forests construct mound nests oriented with their steepest slopes facing south. By angling the nest surface toward the sun, the ants maximize solar heat absorption during the short Finnish summer, raising internal mound temperatures as much as 14°C above ambient levels. This thermal advantage accelerates larval development, enabling colonies to produce a new generation of workers before autumn frosts arrive.', $lyceon_json$[{"key":"A","text":"Wood ants in boreal forests build strategically oriented nests that capture solar heat, accelerating larval growth during a limited warm season."},{"key":"B","text":"The University of Helsinki has pioneered new techniques for studying insect nest architecture in northern Europe."},{"key":"C","text":"Boreal forests experience autumn frosts that are fatal to most wood ant colonies each year."},{"key":"D","text":"Wood ants prefer south-facing hillsides for nesting because the soil there contains more nutrients."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explains that wood ants orient their nests to capture solar heat, raising internal temperatures and accelerating larval development before autumn. The option describing strategically oriented nests that capture solar heat to accelerate larval growth captures this central idea. The option about the University of Helsinki''s research techniques focuses on the institution rather than the finding itself. The option about autumn frosts being fatal overstates a detail — the passage mentions frosts as a deadline, not as a cause of colony death. The option about nutrient-rich soil introduces a claim the passage never makes; the orientation is about solar exposure, not soil composition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W9UP6W', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "currency" most nearly mean?', E'Historian Dagmar Lindqvist argues that the Hanseatic League''s commercial dominance gave its mercantile customs a currency that extended far beyond the Baltic trade routes. Accounting conventions developed in Lübeck warehouses, for instance, were adopted by merchants in Novgorod and Bergen who had no formal ties to the League but recognized the practical advantages of standardized bookkeeping.', $lyceon_json$[{"key":"A","text":"widespread acceptance"},{"key":"B","text":"monetary denomination"},{"key":"C","text":"electrical flow"},{"key":"D","text":"chronological newness"}]$lyceon_json$::jsonb, 'A', NULL, E'Here "currency" describes how mercantile customs gained broad adoption and influence beyond their origin, making "widespread acceptance" the correct meaning. "Monetary denomination" refers to a unit of money, which does not make sense when applied to customs or practices extending beyond trade routes. "Electrical flow" relates to the physics meaning of current and is incoherent in a passage about commercial practices. "Chronological newness" draws on the sense of "current" as recent, but a practice having newness that extends beyond trade routes is nonsensical in this context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WPXB86', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Entomologist Priya Suresh has documented that colonies of the Asian giant honeybee (Apis dorsata) perform a collective defense behavior known as "shimmering," in which hundreds of bees on the surface of the nest raise their abdomens in rapid sequential waves. This synchronized display creates a visual ripple effect that startles approaching predatory wasps and deters them from attacking the colony. _______ shimmering is considered one of the most effective non-contact defense strategies observed in social insects.', $lyceon_json$[{"key":"A","text":"As a result,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Meanwhile,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how shimmering deters predatory wasps, and the sentence after the blank states a consequence of that effectiveness — that shimmering is considered one of the most effective non-contact defense strategies. "As a result," correctly signals that the classification follows from the evidence about the behavior''s deterrent effect. "In contrast," implies an opposing idea is being introduced, but the final sentence continues the same line of reasoning about shimmering''s effectiveness. "Meanwhile," suggests a simultaneous but separate event, yet the sentence draws a conclusion rather than introducing a parallel occurrence. "For example," would introduce a specific illustrative instance, but the final sentence offers a general assessment rather than an example.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WRLXMB', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the botanist''s hypothesis?', E'Botanist Lucia Ferreira hypothesizes that the unusually high density of epiphytic orchids on kapok trees in the central Amazon is due to the kapok''s bark texture. Unlike the smooth bark of neighboring Brazil nut trees, kapok bark is deeply furrowed, creating microhabitats that trap moisture and organic debris. Ferreira proposes that these bark crevices provide epiphytic orchids with the stable moisture and nutrient base they need to germinate and establish root systems.', $lyceon_json$[{"key":"A","text":"Orchid seeds placed on artificially furrowed surfaces germinate at three times the rate of seeds placed on smooth surfaces of identical material."},{"key":"B","text":"Kapok trees produce larger canopies than most other Amazonian tree species."},{"key":"C","text":"Epiphytic orchids in the central Amazon flower more frequently during the wet season than during the dry season."},{"key":"D","text":"Brazil nut trees host a greater diversity of moss species than kapok trees do."}]$lyceon_json$::jsonb, 'A', NULL, E'Ferreira''s hypothesis is that furrowed bark provides the moisture and nutrient conditions orchids need to germinate. The finding that orchid seeds germinate at much higher rates on furrowed surfaces than on smooth ones directly supports the proposed mechanism linking bark texture to orchid establishment. The finding about canopy size addresses a different tree characteristic that is unrelated to bark texture. The finding about seasonal flowering patterns concerns orchid reproduction timing, not the germination conditions Ferreira describes. The finding about moss diversity on Brazil nut trees concerns a different plant group on a different tree species and does not address why orchids favor kapok bark.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
